diff --git a/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs b/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs
index bb073d5ece9..8c7c8299c89 100644
--- a/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs
+++ b/mail/components/inappnotifications/modules/NotificationUpdater.sys.mjs
@@ -30,6 +30,13 @@ export const NotificationUpdater = {
    */
   _updateHistory: [],

+  /**
+   * Version of the schema to be used.
+   *
+   * @type {string}
+   */
+  _SCHEMA_VERSION: "2.0",
+
   /**
    * Reference to the update timeout.
    *
@@ -141,9 +148,7 @@ export const NotificationUpdater = {
       return false;
     }

-    const expirationTime = await this.getRemainingCacheTime(
-      Services.urlFormatter.formatURLPref("mail.inappnotifications.url")
-    );
+    const expirationTime = await this.getRemainingCacheTime(this._getUrl());

     // Don't update if we have an expirationTime unless it's the defaultInterval
     if (expirationTime) {
@@ -154,6 +159,23 @@ export const NotificationUpdater = {
     return !didFetch;
   },

+  /**
+   * Get the url preference with all necessary replacements done and formatted.
+   *
+   * Step 1: Replace version-specific placeholders, such as IAN_SCHEMA_VERSION.
+   * Step 2: Replace placeholders derived from preferences, such as %LOCALE%,
+   *  %OS%, and %CHANNEL%.
+   *
+   * @returns {string} Notification server url.
+   */
+  _getUrl() {
+    const url = Services.prefs.getStringPref("mail.inappnotifications.url");
+
+    return Services.urlFormatter.formatURL(
+      url.replace("%IAN_SCHEMA_VERSION%", this._SCHEMA_VERSION)
+    );
+  },
+
   /**
    * Checks the configured endpoint for json data, which is passed on to the
    * onUpdate callback on this object. Only runs if canUpdate is true.
@@ -177,9 +199,7 @@ export const NotificationUpdater = {
       return false;
     }

-    const url = Services.urlFormatter.formatURLPref(
-      "mail.inappnotifications.url"
-    );
+    const url = this._getUrl();

     if (url === "about:blank" || !url) {
       return false;
diff --git a/mail/components/inappnotifications/test/unit/test_notification_updater.js b/mail/components/inappnotifications/test/unit/test_notification_updater.js
index 8d51581d648..c1b9fd6da99 100644
--- a/mail/components/inappnotifications/test/unit/test_notification_updater.js
+++ b/mail/components/inappnotifications/test/unit/test_notification_updater.js
@@ -520,3 +520,22 @@ add_task(async function test_maxUpdatesPerDay() {

   NotificationUpdater._schedule = schedule;
 });
+
+add_task(async function test_testUrlVersionReplacement() {
+  const url = Services.prefs.getStringPref("mail.inappnotifications.url", "");
+  Services.prefs.setStringPref(
+    "mail.inappnotifications.url",
+    url.replace("notifications.json", "%IAN_SCHEMA_VERSION%/notifications.json")
+  );
+
+  Assert.equal(
+    NotificationUpdater._getUrl(),
+    url.replace(
+      "notifications.json",
+      `${NotificationUpdater._SCHEMA_VERSION}/notifications.json`
+    ),
+    "Correctly replace the version in the url"
+  );
+
+  Services.prefs.setStringPref("mail.inappnotifications.url", url);
+});
